const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<string, Item[]>();
  for (const item of items) {
    const group = groups.get(item.type) ?? [];
    group.push(item);
    groups.set(item.type, group);
  }
  return [...groups.values()];
};

const formsBlock = (sameTypeItems: Item[]): boolean =>
  sameTypeItems.length === BLOCK_SIZE;

const groupBasePremium = (sameTypeItems: Item[]): number =>
  formsBlock(sameTypeItems) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(sameTypeItems);

const policyBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);

