export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  staff: 80,
  amulet: 60,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_PERCENT = 10;

// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
// is 110.00000000000001 in binary floating point. Since the final amount feeds
// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
const addPercent = (amount: number, percent: number): number =>
  amount + (amount * percent) / 100;

const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const sumItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemBasePremium(item), 0);

const allSameType = (items: Item[]): boolean =>
  items.every((item) => item.type === items[0].type);

const formsBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && allSameType(items);

const policyBasePremium = (items: Item[]): number =>
  formsBlock(items) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(items);

const quotePremium = (step: QuoteStep): number =>
  Math.ceil(
    addPercent(policyBasePremium(step.items), FIRST_INSURANCE_PERCENT) +
      PROCESSING_FEE,
  );

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return { premium: quotePremium(step) };
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

