import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Simplest case ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });

  // --- Base premiums per main item type (each + fee) ---
  it("a sword → premium 100 G base + 10 G first insurance + 5 G fee = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("an amulet → premium 60 G base + 6 G first insurance + 5 G fee = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("a staff → premium 80 G base + 8 G first insurance + 5 G fee = 93 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("a potion → premium 40 G base + 4 G first insurance + 5 G fee = 49 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Components and building blocks ---
  it("2 runes → 50 G base premium (+ 5 G first insurance + 5 G fee = 60 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("3 runes → 60 G base premium (block applies) (+ 6 G first insurance + 5 G fee = 71 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("4 runes → 100 G base premium (no block — block requires exactly 3) (= 115 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("7 runes → 175 G base premium (+ 17.5 first insurance + 5 fee = 197.5 → 198 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: Array(7).fill({ type: "rune" }) }],
    });

    expect(result).toEqual({ results: [{ premium: 198 }] });
  });
  it("2 runes + 1 moonstone → 75 G base premium (no block: different types) (= 88 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 88 }] });
  });
  it("3 runes + 3 moonstones → 120 G base premium (two separate blocks) (= 137 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            ...Array(3).fill({ type: "rune" }),
            ...Array(3).fill({ type: "moonstone" }),
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 137 }] });
  });

  // --- Item-scoped modifiers ---
  it.todo("cursed sword adds a 50 % surcharge on the sword's base premium");
  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (+30 %)");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with exactly enchantment 5 → both surcharges apply");

  // --- Modifier scope on multi-item policies ---
  it.todo(
    "cursed sword + plain amulet → policy base 160 G, curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee",
  );

  // --- Policy-scoped modifiers ---
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance adds a 10 % surcharge on the policy base premium");
  it.todo("second contract of a customer → 15 % follow-up discount applies");

  // --- Rounding ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");

  // --- Integration examples ---
  it.todo("newcomer (0 years) with a cursed sword (steel, enchantment 3) → premium 165 G");
  it.todo(
    "long-standing customer (3 years), second quote, cursed sword (steel, enchantment 7) → premium 160 G",
  );

  // --- Claim processing: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("rune (insurance value 250 G), damage 200 G → payout 100 G");

  // --- Claim processing: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Deductible per damage event ---
  it.todo(
    "dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)",
  );

  // --- Insurance sum and cap ---
  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G (block affects premium only), cap 3500 G");
  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");

  // --- Cap exhaustion across successive claims ---
  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Multiple items of the same type ---
  it.todo(
    "two swords insured, dragon attack damages both → each damage entry is a separate damage with its own deductible",
  );
  it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");

  // --- Error cases ---
  it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
  it.todo("claim references a damage entry whose item is not part of the policy → error");
  it.todo("claim references a damage entry with an unknown item type → error");
  it.todo("claim contains a damage entry with amount: -200 → error");
});

