export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  staff: 80,
  amulet: 60,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_PERCENT = 10;

// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
// is 110.00000000000001 in binary floating point. Since the final amount feeds
// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const addPercent = (amount: number, percent: number): number =>
  amount + percentOf(amount, percent);

const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const sumItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemBasePremium(item), 0);

/** Items of one and the same type, e.g. the three runes that form a block. */
type TypeGroup = Item[];

const groupByType = (items: Item[]): TypeGroup[] => [
  ...items
    .reduce(
      (groups, item) =>
        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, TypeGroup>(),
    )
    .values(),
];

const formsBlock = (group: TypeGroup): boolean => group.length === BLOCK_SIZE;

const groupBasePremium = (group: TypeGroup): number =>
  formsBlock(group) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(group);

const policyBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);

const CURSE_PERCENT = 50;

/**
 * Item-scoped modifiers apply to the affected item's own base premium, not to
 * the policy total. Each entry contributes its percentage independently, so
 * several modifiers on one item add up rather than compounding.
 */
const ITEM_SURCHARGE_PERCENTS: { applies: (item: Item) => boolean; percent: number }[] = [
  { applies: (item) => item.cursed === true, percent: CURSE_PERCENT },
];

const itemSurcharge = (item: Item): number =>
  ITEM_SURCHARGE_PERCENTS.filter(({ applies }) => applies(item)).reduce(
    (surcharge, { percent }) => surcharge + percentOf(itemBasePremium(item), percent),
    0,
  );

const totalItemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemSurcharge(item), 0);

const quotePremium = (step: QuoteStep): number =>
  Math.ceil(
    addPercent(policyBasePremium(step.items), FIRST_INSURANCE_PERCENT) +
      totalItemSurcharges(step.items) +
      PROCESSING_FEE,
  );

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return { premium: quotePremium(step) };
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

