export const runScenario = (scenario: Scenario): ScenarioResult => {
  const remainingCapByPolicy = new Map<number, number>();
  const results: StepResult[] = [];

  scenario.steps.forEach((step, index) => {
    if (step.op === "quote") {
      remainingCapByPolicy.set(index, CAP_MULTIPLE * insuranceSum(step.items));
      results.push({
        premium: quotePremium(step, {
          customer: scenario.customer,
          precedingQuoteCount: countQuotes(scenario.steps.slice(0, index)),
          steps: scenario.steps,
        }),
      });
      return;
    }

    const insuredItems = policyAt(scenario.steps, step.policy)?.items ?? [];
    const result = claimResult(
      step,
      insuredItems,
      remainingCapByPolicy.get(step.policy) ?? 0,
    );
    remainingCapByPolicy.set(step.policy, result.remainingCap);
    results.push(result);
  });

  return { results };
};

