/**
 * The insured item a damage entry refers to. The MHPCO pays only for what it
 * insures, so a damage naming a type the policy does not cover — whether an
 * uninsured item or an unknown one — voids the whole claim.
 */
const damagedItem = (insuredItems: Item[], damage: Damage): Item => {
  const item = insuredItems.find((insured) => insured.type === damage.itemType);
  if (item === undefined) {
    throw new Error(
      `The policy does not cover an item of type "${damage.itemType}"`,
    );
  }
  return item;
};

const totalPayout = (damages: Damage[], insuredItems: Item[]): number =>
  Math.floor(
    damages.reduce(
      (sum, damage) => sum + damagePayout(damage, damagedItem(insuredItems, damage)),
      0,
    ),
  );

