import { describe, it, expect } from "vitest";
import { execFile } from "node:child_process";
import { promisify } from "node:util";

const run = async (
  stdin: string,
): Promise<{ stdout: string; stderr: string; code: number }> => {
  const child = execFile("npx", ["tsx", "src/cli.ts"]);
  child.stdin?.end(stdin);

  const [stdout, stderr] = await Promise.all([
    collect(child.stdout),
    collect(child.stderr),
  ]);
  const code = await new Promise<number>((resolve) =>
    child.on("close", (exitCode) => resolve(exitCode ?? 0)),
  );

  return { stdout, stderr, code };
};

const collect = (stream: NodeJS.ReadableStream | null): Promise<string> =>
  new Promise((resolve) => {
    if (!stream) return resolve("");
    let text = "";
    stream.on("data", (chunk) => (text += chunk));
    stream.on("end", () => resolve(text));
  });

const SCENARIO = JSON.stringify({
  customer: { yearsWithMHPCO: 5 },
  steps: [
    {
      op: "quote",
      items: [
        { type: "amulet", material: "silver", enchantment: 2, cursed: false },
      ],
    },
    {
      op: "claim",
      policy: 0,
      incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] },
    },
  ],
});

describe("claim-office CLI", () => {
  it("reads a scenario from stdin and writes the results JSON to stdout", async () => {
    const { stdout, code } = await run(SCENARIO);

    expect(code).toBe(0);
    expect(JSON.parse(stdout)).toEqual({
      results: [{ premium: 51 }, { payout: 100, remainingCap: 1100 }],
    });
  });

  it.todo("exits non-zero and describes the error on stderr for an invalid scenario");
  it.todo("writes no results to stdout when the scenario is rejected");
});

