const REJECTED = 1;

/**
 * A rejected scenario is reported as a one-line description on stderr; the
 * stack trace is of no use to whoever piped the JSON in, and stdout stays
 * empty so that no partial result can be mistaken for an answer.
 */
const main = async (): Promise<void> => {
  const input = await readStdin();

  try {
    const scenario = JSON.parse(input) as Scenario;
    const result = runScenario(scenario);
    process.stdout.write(JSON.stringify(result));
  } catch (error) {
    process.stderr.write(`${(error as Error).message}\n`);
    process.exitCode = REJECTED;
  }
};

await main();

